// === Tab: Sketch ===
// By Roni Kaufman
// inspired by https://twitter.com/dmitricherniak/status/1214888292421951488?s=09

let particles = [];
let circles = [];
let squiggliness = 1/1000;
let interval;
let margin = 20;
let theEnd = false;

function setup() {
  createCanvas(500, 500);
  colorMode(HSB, 100);
  noStroke();

  background(0);
  updateParticles();

  interval = setInterval(updateParticles, 2000);
}

function draw() {
	if (theEnd) {
		strokeWeight(8);
		stroke(100);
		noFill();
		line(1, 1, 1, height-1);
		line(1, height-1, width-1, height-1);
		line(width-1, height-1, width-1, 1);
		line(width-1, 1, 1, 1);
		// noLoop() removed for animation
	} else {
		for (let p of particles) {
			p.draw();
			p.move();
		}
	}
}

function updateParticles() {
  particles = [];
	let r = random(10, 50);
	let xCenter = random(margin, width - margin);
	let yCenter = random(margin, height - margin);
	let attempts = 0;
	while (intersectsWithOtherCircles(xCenter, yCenter, r)) {
		r = random(10, 50);
		xCenter = random(margin, width - margin);
		yCenter = random(margin, height - margin);
		attempts++;
		if (attempts > 1000) {
			clearInterval(interval);
			theEnd = true;
			return;
		}
	}
	let n = r*10;
  for (let i = 0; i < n; i++) {
		let theta = map(i, 0, n, -PI, PI);
    let x_ = xCenter + r*cos(theta);
    let y_ = yCenter + r*sin(theta);
		let s_ = 1;
    particles.push(new Particle(x_, y_, s_));
  }
}

function Particle(x_, y_, s_) {
  this.x = x_;
  this.y = y_;
  this.size = s_;

  this.alpha = 100;
  this.dist = 1.2;

  this.move = function() {
    var theta = noise(this.x * squiggliness, this.y * squiggliness)*PI*10;
    let v = p5.Vector.fromAngle(theta, this.dist);
    this.x += v.x;
    this.y += v.y;
    //this.dist *= 0.999;
    this.alpha *= 0.98;
		this.size *= 0.98;
  }

  this.draw = function() {
    fill(100, this.alpha);
    circle(this.x, this.y, this.size);
  }
}

function intersectsWithOtherCircles(x_, y_, r_) {
	for (let c of circles) {
		if (dist(c.x, c.y, x_, y_) < c.r + r_ + margin) {
			return true;
		}
	}
	circles.push({x: x_, y: y_, r: r_});
	return false;
}
